arguments.command:
cd /tmp && python3 -c "
import json
d=json.load(open('fp.json'))
pdbs=set(open('/app/pdb_ids.txt').read().split())
for p in d:
    if set(p.get('pdb') or []) & pdbs:
        for s in p['states']: print(p['name'],p['pdb'],s['name'],s['ex_max'],s['em_max'])
"

